23	// ---------------------------------------------------------------------------
24	// Subprocess helper: fake llama-server
25	//
26	// Tests that need a real process invoke the test binary itself with
27	// GO_WANT_HELPER_PROCESS=1 and -test.run=TestHelperProcess.
28	// The subprocess then acts as a minimal llama-server on the requested port.
29	//
30	// Supported extra flags (after "--"):
31	//   --health-delay-ms=N   delay GET /health by N milliseconds before responding 200
32	//   --fail                exit immediately without starting the HTTP server
33	// ---------------------------------------------------------------------------
34	
35	// TestHelperProcess is NOT a real test — it is a subprocess target.
36	func TestHelperProcess(t *testing.T) {
37		if os.Getenv("GO_WANT_HELPER_PROCESS") != "1" {
38			return
39		}
40	
41		// Locate args after "--"
42		args := os.Args
43		for i, a := range args {
44			if a == "--" {
45				args = args[i+1:]
46				break
47			}
48		}
49	
50		if len(args) == 0 || args[0] != "llama-server" {
51			fmt.Fprintln(os.Stderr, "expected llama-server as first arg")
52			os.Exit(2)
53		}
54	
55		// Parse flags from remaining args.
56		port := "8080"
57		healthDelayMs := 0
58		fail := false
59		for i, a := range args[1:] {
60			if a == "--port" && i+1 < len(args[1:]) {
61				port = args[1:][i+1]
62			}
63			if strings.HasPrefix(a, "--health-delay-ms=") {
64				ms, _ := strconv.Atoi(strings.TrimPrefix(a, "--health-delay-ms="))
65				healthDelayMs = ms
66			}
67			if a == "--fail" {
68				fail = true
69			}
70		}
71	
72		if fail {
73			os.Exit(1)
74		}
75	
76		mux := http.NewServeMux()
77		mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
78			if healthDelayMs > 0 {
79				time.Sleep(time.Duration(healthDelayMs) * time.Millisecond)
80			}
81			w.WriteHeader(http.StatusOK)
82		})
83	
84		// Use port 0 to let the OS pick a free port, then print the listening
85		// line that wire's event parser expects.
86		listener, err := net.Listen("tcp", ":"+port)
87		if err != nil {
88			fmt.Fprintf(os.Stderr, "listen: %v\n", err)
89			os.Exit(2)
90		}
91		actualPort := listener.Addr().(*net.TCPAddr).Port
92		fmt.Fprintf(os.Stdout, "main: server is listening on http://127.0.0.1:%d\n", actualPort)
93	
94		srv := &http.Server{Handler: mux}
95		go srv.Serve(listener) //nolint:errcheck
96	
97		sigCh := make(chan os.Signal, 1)
98		signal.Notify(sigCh, syscall.SIGTERM, syscall.SIGINT)
99		<-sigCh
100	
101		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
102		defer cancel()
103		srv.Shutdown(ctx) //nolint:errcheck
104		os.Exit(0)
105	}
