107	// testCmdBuilder returns a cmdBuilder that runs the test binary as a fake
108	// llama-server subprocess.
109	func testCmdBuilder(ctx context.Context, modelName string, params config.ModelParams) *exec.Cmd {
110		args := append(
111			[]string{"-test.run=TestHelperProcess", "--", "llama-server"},
112			buildArgs(modelName, params)...,
113		)
114		cmd := exec.CommandContext(ctx, os.Args[0], args...)
115		cmd.Env = append(os.Environ(), "GO_WANT_HELPER_PROCESS=1")
116		return cmd
117	}
118	
119	// testCmdBuilderWithDelay is like testCmdBuilder but the health endpoint
120	// sleeps for delayMs milliseconds before responding 200. Used to exercise
121	// the "concurrent requests coalesce" and "context cancellation" scenarios.
122	func testCmdBuilderWithDelay(delayMs int) func(context.Context, string, config.ModelParams) *exec.Cmd {
123		return func(ctx context.Context, modelName string, params config.ModelParams) *exec.Cmd {
124			args := append(
125				[]string{"-test.run=TestHelperProcess", "--", "llama-server"},
126				buildArgs(modelName, params)...,
127			)
128			args = append(args, fmt.Sprintf("--health-delay-ms=%d", delayMs))
129			cmd := exec.CommandContext(ctx, os.Args[0], args...)
130			cmd.Env = append(os.Environ(), "GO_WANT_HELPER_PROCESS=1")
131			return cmd
132		}
133	}
134	
135	// failCmdBuilder returns a cmdBuilder whose process always exits immediately
136	// without starting an HTTP server — simulating a model that fails to load.
137	func failCmdBuilder(ctx context.Context, modelName string, params config.ModelParams) *exec.Cmd {
138		args := append(
139			[]string{"-test.run=TestHelperProcess", "--", "llama-server"},
140			buildArgs(modelName, params)...,
141		)
142		args = append(args, "--fail")
143		cmd := exec.CommandContext(ctx, os.Args[0], args...)
144		cmd.Env = append(os.Environ(), "GO_WANT_HELPER_PROCESS=1")
145		return cmd
146	}
