148	// newTestManager creates a Manager wired to the fake llama-server subprocess.
149	func newTestManager(cfg *config.Config) *Manager {
150		m := New(cfg, slog.Default())
151		m.cmdBuilder = testCmdBuilder
152		return m
153	}
