277	func TestManager_StartStop(t *testing.T) {
278		cfg := &config.Config{
279			Models: map[string]config.ModelParams{
280				"org/test-model": {Slots: 1},
281			},
282			Warmup:    []string{"org/test-model"},
283			MaxModels: 1,
284		}
285		m := newTestManager(cfg)
286	
287		ctx, cancel := context.WithCancel(context.Background())
288		defer cancel()
289	
290		if err := m.Start(ctx); err != nil {
291			t.Fatalf("Start: %v", err)
292		}
293	
294		// Poll until healthy (up to 10s for the subprocess to spin up).
295		deadline := time.Now().Add(10 * time.Second)
296		for time.Now().Before(deadline) {
297			if m.Loaded("org/test-model") {
298				break
299			}
300			time.Sleep(100 * time.Millisecond)
301		}
302	
303		if !m.Loaded("org/test-model") {
304			t.Fatal("model did not become healthy within 10s")
305		}
306	
307		addr, ok := m.Addr("org/test-model")
308		if !ok {
309			t.Fatal("Addr: expected ok=true after healthy")
310		}
311		if addr == "" {
312			t.Error("Addr: returned empty string")
313		}
314	
315		running := m.RunningModels()
316		if len(running) != 1 || running[0] != "org/test-model" {
317			t.Errorf("RunningModels: got %v, want [org/test-model]", running)
318		}
319	
320		if err := m.Stop(); err != nil {
321			t.Errorf("Stop: %v", err)
322		}
323	
324		if m.Loaded("org/test-model") {
325			t.Error("Loaded: expected false after Stop")
326		}
327	}
