333	// TestLoadOrGet_Coalescing verifies that 10 concurrent requests for the same
334	// unloaded model coalesce to a single process start.
335	func TestLoadOrGet_Coalescing(t *testing.T) {
336		cfg := &config.Config{
337			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
338			MaxModels: 1,
339		}
340		m := New(cfg, slog.Default())
341		// 200 ms startup delay to ensure all goroutines arrive before healthy.
342		m.cmdBuilder = testCmdBuilderWithDelay(200)
343	
344		ctx, cancel := context.WithCancel(context.Background())
345		defer cancel()
346		if err := m.Start(ctx); err != nil {
347			t.Fatalf("Start: %v", err)
348		}
349	
350		params := config.ModelParams{Slots: 1}
351		const n = 10
352		addrs := make([]string, n)
353		var wg sync.WaitGroup
354		wg.Add(n)
355		for i := range n {
356			go func(i int) {
357				defer wg.Done()
358				addr, release, err := m.LoadOrGet(ctx, "org/model-a", params)
359				if err != nil {
360					t.Errorf("goroutine %d: LoadOrGet error: %v", i, err)
361					return
362				}
363				defer release()
364				addrs[i] = addr
365			}(i)
366		}
367		wg.Wait()
368	
369		// All goroutines must have gotten a non-empty addr.
370		first := addrs[0]
371		if first == "" {
372			t.Fatal("got empty addr")
373		}
374		for i, a := range addrs {
375			if a != first {
376				t.Errorf("goroutine %d: got addr %q, want %q (coalescing failed)", i, a, first)
377			}
378		}
379	
380		// Only one process should have been started.
381		if len(m.RunningModels()) != 1 {
382			t.Errorf("RunningModels: expected 1, got %d", len(m.RunningModels()))
383		}
384	}
