386	// TestLoadOrGet_LRUEviction verifies that when max_models=1 and model A is
387	// loaded, requesting model B evicts A and loads B. Requesting A again evicts B
388	// and reloads A.
389	func TestLoadOrGet_LRUEviction(t *testing.T) {
390		cfg := &config.Config{
391			Models: map[string]config.ModelParams{
392				"org/model-a": {Slots: 1},
393				"org/model-b": {Slots: 1},
394			},
395			Warmup:    []string{"org/model-a"},
396			MaxModels: 1,
397		}
398		m := newTestManager(cfg)
399	
400		ctx, cancel := context.WithCancel(context.Background())
401		defer cancel()
402		if err := m.Start(ctx); err != nil {
403			t.Fatalf("Start: %v", err)
404		}
405	
406		// Wait for warmup model A to become healthy.
407		waitLoadedModel(t, m, "org/model-a", 10*time.Second)
408	
409		// Request model B: should evict A and load B.
410		addrB, releaseB, err := m.LoadOrGet(ctx, "org/model-b", cfg.Models["org/model-b"])
411		if err != nil {
412			t.Fatalf("LoadOrGet model-b: %v", err)
413		}
414		if addrB == "" {
415			t.Fatal("got empty addr for model-b")
416		}
417		releaseB()
418	
419		if m.Loaded("org/model-a") {
420			t.Error("model-a should have been evicted")
421		}
422		if !m.Loaded("org/model-b") {
423			t.Error("model-b should be healthy")
424		}
425	
426		// Request model A again: should evict B and reload A.
427		addrA2, releaseA2, err := m.LoadOrGet(ctx, "org/model-a", cfg.Models["org/model-a"])
428		if err != nil {
429			t.Fatalf("LoadOrGet model-a (reload): %v", err)
430		}
431		if addrA2 == "" {
432			t.Fatal("got empty addr for model-a reload")
433		}
434		releaseA2()
435	
436		if m.Loaded("org/model-b") {
437			t.Error("model-b should have been evicted on second request")
438		}
439		if !m.Loaded("org/model-a") {
440			t.Error("model-a should be healthy after reload")
441		}
442	}
