444	// TestLoadOrGet_InFlightProtection verifies that a model with an active
445	// in-flight request cannot be evicted; the caller gets a 503-style error.
446	func TestLoadOrGet_InFlightProtection(t *testing.T) {
447		cfg := &config.Config{
448			Models: map[string]config.ModelParams{
449				"org/model-a": {Slots: 1},
450				"org/model-b": {Slots: 1},
451			},
452			Warmup:    []string{"org/model-a"},
453			MaxModels: 1,
454		}
455		m := newTestManager(cfg)
456	
457		ctx, cancel := context.WithCancel(context.Background())
458		defer cancel()
459		if err := m.Start(ctx); err != nil {
460			t.Fatalf("Start: %v", err)
461		}
462	
463		waitLoadedModel(t, m, "org/model-a", 10*time.Second)
464	
465		// Hold an in-flight request against model A.
466		_, releaseA, err := m.LoadOrGet(ctx, "org/model-a", cfg.Models["org/model-a"])
467		if err != nil {
468			t.Fatalf("LoadOrGet model-a: %v", err)
469		}
470		// Do NOT call releaseA yet — this keeps inflight > 0.
471	
472		// Requesting model B at max_models=1 must fail because A has in-flight requests.
473		_, _, err = m.LoadOrGet(ctx, "org/model-b", cfg.Models["org/model-b"])
474		if err == nil {
475			t.Fatal("expected error when trying to evict a model with in-flight requests, got nil")
476		}
477	
478		// Now release A; the next request for B should succeed.
479		releaseA()
480	
481		_, releaseB, err := m.LoadOrGet(ctx, "org/model-b", cfg.Models["org/model-b"])
482		if err != nil {
483			t.Fatalf("LoadOrGet model-b after release: %v", err)
484		}
485		releaseB()
486	}
