488	// TestLoadOrGet_ContextCancellation verifies that cancelling the requesting
489	// context does not abort the model load. A second request for the same model
490	// (with a valid context) should join the in-progress load.
491	func TestLoadOrGet_ContextCancellation(t *testing.T) {
492		cfg := &config.Config{
493			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
494			MaxModels: 1,
495		}
496		m := New(cfg, slog.Default())
497		// 400 ms delay so we can cancel the first request mid-load.
498		m.cmdBuilder = testCmdBuilderWithDelay(400)
499	
500		bgCtx, cancel := context.WithCancel(context.Background())
501		defer cancel()
502		if err := m.Start(bgCtx); err != nil {
503			t.Fatalf("Start: %v", err)
504		}
505	
506		params := config.ModelParams{Slots: 1}
507	
508		// First request: cancel the context almost immediately.
509		cancelCtx, cancelFn := context.WithCancel(bgCtx)
510		cancelFn() // cancel before LoadOrGet returns
511	
512		_, _, err := m.LoadOrGet(cancelCtx, "org/model-a", params)
513		if err == nil {
514			t.Log("first request: LoadOrGet returned before context cancelled (load was fast)")
515		} else if !errors.Is(err, context.Canceled) {
516			t.Fatalf("first request: expected context.Canceled, got %v", err)
517		}
518	
519		// The supervisor should still be running (using the manager's detached context).
520		// A second request with a valid context should succeed.
521		addr, release, err := m.LoadOrGet(bgCtx, "org/model-a", params)
522		if err != nil {
523			t.Fatalf("second LoadOrGet: %v", err)
524		}
525		defer release()
526		if addr == "" {
527			t.Fatal("second LoadOrGet: got empty addr")
528		}
529	}
