531	// TestLoadOrGet_LoadFailure verifies that when a model fails to start, all
532	// concurrent waiters receive an error and the model is removed from procs.
533	func TestLoadOrGet_LoadFailure(t *testing.T) {
534		cfg := &config.Config{
535			Models:    map[string]config.ModelParams{"org/bad-model": {Slots: 1}},
536			MaxModels: 2,
537		}
538		m := New(cfg, slog.Default())
539		m.cmdBuilder = failCmdBuilder            // process exits immediately
540		m.healthTimeout = 500 * time.Millisecond // short timeout so test is fast
541	
542		bgCtx, cancel := context.WithCancel(context.Background())
543		defer cancel()
544		if err := m.Start(bgCtx); err != nil {
545			t.Fatalf("Start: %v", err)
546		}
547	
548		params := config.ModelParams{Slots: 1}
549		const n = 5
550		var wg sync.WaitGroup
551		errs := make([]error, n)
552		wg.Add(n)
553		for i := range n {
554			go func(i int) {
555				defer wg.Done()
556				_, _, errs[i] = m.LoadOrGet(bgCtx, "org/bad-model", params)
557			}(i)
558		}
559		wg.Wait()
560	
561		// All waiters must have received an error.
562		for i, err := range errs {
563			if err == nil {
564				t.Errorf("goroutine %d: expected load error, got nil", i)
565			}
566		}
567	
568		// Model must not appear in ListModels (state idle = excluded).
569		for _, mi := range m.ListModels() {
570			if mi.ID == "org/bad-model" {
571				t.Errorf("failed model still visible in ListModels with status %q", mi.Status)
572			}
573		}
574	}
