620	// TestReload_ParamsChanged verifies that a model with changed params is drained
621	// and restarted by Reload.
622	func TestReload_ParamsChanged(t *testing.T) {
623		cfg := &config.Config{
624			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
625			Warmup:    []string{"org/model-a"},
626			MaxModels: 1,
